content.content:
1	'use strict';
2	
3	// The remote port's web page: pairs from the fragment of the URL the
4	// host's QR code carries, lists the sessions with the waiting ones
5	// first, shows a session's last response or screen, and sends a reply.
6	// It speaks what the headset speaks (docs/remote-client.md §4) and
7	// keeps nothing but the host's public identity; the credential is a
8	// cookie this script cannot read. Plain DOM, `textContent` only, no
9	// dependency. The pure parts at the top are what `app.test.js` covers.
10	
11	// Every path the page reads, in one place so a test can check that the
12	// host answers each. `{id}` is a project's id under `/projects/` and a
13	// session's elsewhere.
14	const API = {
15	  info: '/api/v1/info',
16	  pair: '/api/v1/pair',
17	  me: '/api/v1/me',
18	  projects: '/api/v1/projects',
19	  sessions: '/api/v1/projects/{id}/sessions',
20	  waiting: '/api/v1/waiting',
21	  lastResponse: '/api/v1/sessions/{id}/last-response',
22	  screen: '/api/v1/sessions/{id}/screen',
23	  send: '/api/v1/sessions/{id}/send',
24	  events: '/api/v1/events',
25	};
26	
27	const STORAGE_KEY = 'switchboard-host';
28	const POLL_MS = 3000;
29	const POLL_SLOW_MS = 20000;
30	const SOCKET_RETRY_MS = 5000;
31	const SOCKET_RETRY_MAX_MS = 60000;
32	
33	// --- pure parts
34	
35	// The pairing values in a URL fragment: `#code=…&key=…&id=…`, or null
36	// when any of the three is missing.
37	function parseFragment(hash) {
38	  const text = (hash || '').replace(/^#/, '');
39	  if (!text) return null;
40	  const values = {};
41	  for (const pair of text.split('&')) {
42	    const at = pair.indexOf('=');
43	    if (at <= 0) continue;
44	    const name = decodeURIComponent(pair.slice(0, at));
45	    const value = decodeURIComponent(pair.slice(at + 1));
46	    values[name] = value;
47	  }
48	  if (!values.code || !values.key || !values.id) return null;
49	  return { code: values.code, key: values.key, id: values.id };
50	}
51	
52	// What the host lists this browser as: the browser "on" the device,
53	// from the user agent, with a Macintosh that reports touch counted as
54	// an iPad (Safari on iPadOS says Macintosh).
55	function deviceName(userAgent, touchPoints) {
56	  const ua = userAgent || '';
57	  let browser = 'Safari';
58	  if (/Edg\//.test(ua)) browser = 'Edge';
59	  else if (/Chrome\//.test(ua)) browser = 'Chrome';
60	  else if (/Firefox\//.test(ua)) browser = 'Firefox';
61	  let device = '';
62	  if (/iPhone/.test(ua)) device = 'iPhone';
63	  else if (/iPad/.test(ua)) device = 'iPad';
64	  else if (/Macintosh/.test(ua)) device = touchPoints > 1 ? 'iPad' : 'Mac';
65	  else if (/Android/.test(ua)) device = 'Android';
66	  else if (/Windows/.test(ua)) device = 'Windows';
67	  else if (/Linux/.test(ua)) device = 'Linux';
68	  if (!browser && !device) return 'Browser';
69	  return device ? `${browser} on ${device}` : browser;
70	}
71	
72	// Why a request was refused 401, told from `/info`, which the page can
73	// read unpaired: `stored` is what the page kept of the host it paired
74	// with, `info` the body `/info` answered now or null when it did not.
75	// The host cannot say "revoked" (a revoked token and an unknown one are
76	// the same refusal), so the page infers it from the identity standing.
77	function inferUnauthorized(stored, info) {
78	  if (!info) return 'unreachable';
79	  if (!stored) return 'not_paired';
80	  if (stored.server_id === info.server_id && stored.spki_sha256 === info.spki_sha256) {
81	    return 'removed';
82	  }
83	  return 'identity_changed';
84	}
85	
86	const UNAUTHORIZED_TEXT = {
87	  unreachable: ['Can\'t reach the host', 'The Mac did not answer. Check that it is on and on this network.'],
88	  not_paired: ['Not paired', 'Open Remote devices on the Mac, allow pairing, and scan its code with this phone.'],
89	  removed: ['Removed on the host', 'This device was removed on the Mac. Open its pairing window and scan the code again.'],
90	  identity_changed: ['Identity changed', 'The host at this address is not the one this browser paired with, or its key was remade. Pair again from its window.'],
91	};
92	
93	// Whether a reply at (epoch, revision) is at or past what the page
94	// holds (§4.4): a reply from an earlier revision is dropped, and a new
95	// epoch (the host restarted) always applies.
96	function accepts(held, reply) {
97	  if (!held) return true;
98	  if (held.epoch !== reply.epoch) return true;
99	  return reply.revision >= held.revision;
100	}
101	
102	// The list as the page shows it: projects with a waiting session
103	// first, waiting sessions first within a project, then by last
104	// activity, newest first, name as the tie-break. Pure over the two
105	// replies so a test can call it.
106	function orderList(projects, sessionsByProject) {
107	  const groups = projects.map((project) => {
108	    const sessions = (sessionsByProject[project.id] || []).slice();
109	    sessions.sort((a, b) => {
110	      if (Boolean(a.waiting) !== Boolean(b.waiting)) return a.waiting ? -1 : 1;
111	      const ta = a.last_activity_ms || 0;
112	      const tb = b.last_activity_ms || 0;
113	      if (ta !== tb) return tb - ta;
114	      return String(a.name).localeCompare(String(b.name));
115	    });
116	    return { project, sessions, waiting: sessions.some((s) => s.waiting) };
117	  });
118	  groups.sort((a, b) => {
119	    if (a.waiting !== b.waiting) return a.waiting ? -1 : 1;
120	    return String(a.project.name).localeCompare(String(b.project.name));
121	  });
122	  return groups;
123	}
124	
125	// "3 m ago", "2 h ago"; '' with no time.
126	function sinceText(ms, now) {
127	  if (!ms) return '';
128	  const s = Math.max(0, Math.floor((now - ms) / 1000));
129	  if (s < 60) return 'just now';
130	  const m = Math.floor(s / 60);
131	  if (m < 60) return `${m} m ago`;
132	  const h = Math.floor(m / 60);
133	  if (h < 48) return `${h} h ago`;
134	  return `${Math.floor(h / 24)} d ago`;
135	}
136	
137	// The reply box's operation id: random hex, kept across a retry so a
138	// send whose reply was lost is answered from the host's log rather
139	// than typed twice. `getRandomValues` exists outside a secure context.
140	function newOp(randomValues) {
141	  const bytes = new Uint8Array(16);
142	  randomValues(bytes);
143	  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
144	}
145	
146	if (typeof module !== 'undefined' && module.exports) {
147	  module.exports = {
148	    API,
149	    parseFragment,
150	    deviceName,
151	    inferUnauthorized,
152	    accepts,
153	    orderList,
154	    sinceText,
155	    newOp,
156	  };
157	}
158	
159	// --- the page
160	
161	if (typeof document !== 'undefined') {
162	  const $ = (id) => document.getElementById(id);
163	
164	  const state = {
165	    me: null,
166	    stored: null,
167	    held: null,
168	    groups: [],
169	    open: null,
170	    openView: null,
171	    pendingOp: null,
172	    socket: null,
173	    socketRetryMs: SOCKET_RETRY_MS,
174	    pollTimer: null,
175	    pollMs: POLL_MS,
176	  };
177	
178	  function show(section) {
179	    for (const id of ['boot', 'notice', 'list', 'session']) {
180	      $(id).hidden = id !== section;
181	    }
182	  }
183	
184	  function notice(title, text) {
185	    $('notice-title').textContent = title;
186	    $('notice-text').textContent = text;
187	    show('notice');
188	  }
189	
190	  function loadStored() {
191	    try {
192	      const text = localStorage.getItem(STORAGE_KEY);
193	      return text ? JSON.parse(text) : null;
194	    } catch (e) {
195	      return null;
196	    }
197	  }
198	
199	  function saveStored(value) {
200	    try {
201	      localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
202	    } catch (e) {
203	      // Private browsing may refuse; the page then forgets on reload.
204	    }
205	    state.stored = value;
206	  }
207	
208	  // One request to the host; the cookie rides along as the browser's
209	  // own credential. The reply is the parsed envelope with its status.
210	  async function api(method, path, body) {
211	    const init = { method, credentials: 'same-origin', headers: {} };
212	    if (body !== undefined) {
213	      init.headers['Content-Type'] = 'application/json';
214	      init.body = JSON.stringify(body);
215	    }
216	    let response;
217	    try {
218	      response = await fetch(path, init);
219	    } catch (e) {
220	      return { status: 0, json: null };
221	    }
222	    let json = null;
223	    try {
224	      json = await response.json();
225	    } catch (e) {
226	      json = null;
227	    }
228	    return { status: response.status, json };
229	  }
230	
231	  function errorCode(reply) {
232	    return reply.json && reply.json.error ? reply.json.error.code : '';
233	  }
234	
235	  async function unauthorized() {
236	    stopRefresh();
237	    const info = await api('GET', API.info);
238	    const kind = inferUnauthorized(state.stored, info.status === 200 ? info.json.body : null);
239	    const [title, text] = UNAUTHORIZED_TEXT[kind];
240	    notice(title, text);
241	  }
242	
243	  // The reply, or null after a refusal was shown.
244	  async function read(path) {
245	    const reply = await api('GET', path);
246	    if (reply.status === 401) {
247	      await unauthorized();
248	      return null;
249	    }
250	    if (reply.status === 0) {
251	      notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
252	      return null;
253	    }
254	    return reply;
255	  }
256	
257	  async function boot() {
258	    state.stored = loadStored();
259	    const fragment = parseFragment(location.hash);
260	    if (fragment) {
261	      // The code leaves the address bar before anything else happens.
262	      history.replaceState(null, '', location.pathname);
263	      await pair(fragment);
264	      return;
265	    }
266	    const me = await api('GET', API.me);
267	    if (me.status === 200) {
268	      becamePaired(me.json.body);
269	      return;
270	    }
271	    if (me.status === 401) {
272	      await unauthorized();
273	      return;
274	    }
275	    notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
276	  }
277	
278	  const PAIR_TEXT = {
279	    pairing_closed: 'The pairing window on the Mac is closed. Allow pairing again and scan the new code.',
280	    wrong_code: 'The code does not match. Scan the code the Mac shows now.',
281	    wrong_key: 'This is not the host the code was scanned from.',
282	    rate_limited: 'Too many pairing attempts. Wait a minute and scan again.',
283	  };
284	
285	  async function pair(fragment) {
286	    $('boot-text').textContent = 'Pairing…';
287	    const info = await api('GET', API.info);
288	    if (info.status !== 200) {
289	      notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
290	      return;
291	    }
292	    const host = info.json.body;
293	    if (host.spki_sha256 !== fragment.key || host.server_id !== fragment.id) {
294	      notice('Different host', 'This address is a different Switchboard than the code was for. Nothing was sent.');
295	      return;
296	    }
297	    const reply = await api('POST', API.pair, {
298	      code: fragment.code,
299	      spki_sha256: fragment.key,
300	      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints || 0),
301	      transport: 'cookie',
302	    });
303	    if (reply.status !== 200) {
304	      const code = errorCode(reply);
305	      notice('Not paired', PAIR_TEXT[code] || `The host refused the pairing (${code || reply.status}).`);
306	      return;
307	    }
308	    saveStored({
309	      server_id: host.server_id,
310	      spki_sha256: host.spki_sha256,
311	      server_name: host.server_name,
312	    });
313	    const me = await api('GET', API.me);
314	    if (me.status !== 200) {
315	      await unauthorized();
316	      return;
317	    }
318	    becamePaired(me.json.body);
319	  }
320	
321	  function becamePaired(me) {
322	    state.me = me;
323	    $('host-name').textContent = me.server_name;
324	    $('scope').textContent = me.scope;
325	    $('header').hidden = false;
326	    show('list');
327	    refreshAll();
328	    startRefresh();
329	  }
330	
331	  async function refreshMe() {
332	    const reply = await read(API.me);
333	    if (reply && reply.status === 200) {
334	      state.me = reply.json.body;
335	      $('scope').textContent = state.me.scope;
336	    }
337	  }
338	
339	  // --- the list
340	
341	  async function refreshList() {
342	    const projects = await read(API.projects);
343	    if (!projects || projects.status !== 200) return;
344	    const list = projects.json.body.projects || [];
345	    const sessionsByProject = {};
346	    for (const project of list) {
347	      const reply = await read(API.sessions.replace('{id}', project.id));
348	      if (!reply) return;
349	      sessionsByProject[project.id] = reply.status === 200 ? reply.json.body.sessions || [] : [];
350	    }
351	    state.groups = orderList(list, sessionsByProject);
352	    renderList();
353	  }
354	
355	  function renderList() {
356	    const root = $('projects');
357	    root.textContent = '';
358	    const now = Date.now();
359	    let count = 0;
360	    for (const group of state.groups) {
361	      if (group.sessions.length === 0) continue;
362	      const title = document.createElement('h2');
363	      title.textContent = group.project.name;
364	      root.appendChild(title);
365	      for (const session of group.sessions) {
366	        count += 1;
367	        const row = document.createElement('button');
368	        row.type = 'button';
369	        row.className = session.waiting ? 'session-row is-waiting' : 'session-row';
370	        if (session.waiting) {
371	          const waiting = document.createElement('span');
372	          waiting.className = 'line waiting';
373	          waiting.textContent = session.waiting_reason
374	            ? `Waiting on you: ${session.waiting_reason}`
375	            : 'Waiting on you';
376	          row.appendChild(waiting);
377	        }
378	        const name = document.createElement('span');
379	        name.className = 'line name';
380	        name.textContent = session.name;
381	        row.appendChild(name);
382	        const meta = document.createElement('span');
383	        meta.className = 'line meta';
384	        const since = sinceText(session.last_activity_ms, now);
385	        meta.textContent = [session.kind, session.card, since].filter(Boolean).join(' · ');
386	        row.appendChild(meta);
387	        row.addEventListener('click', () => openSession(session));
388	        root.appendChild(row);
389	      }
390	    }
391	    $('list-empty').hidden = count !== 0;
392	  }
393	
394	  // --- a session
395	
396	  function openSession(session) {
397	    state.open = session;
398	    state.pendingOp = null;
399	    $('session-name').textContent = session.name;
400	    $('session-text').textContent = '';
401	    $('session-truncated').hidden = true;
402	    $('send-status').textContent = '';
403	    $('reply-text').value = '';
404	    show('session');
405	    renderSessionMeta();
406	    refreshSession();
407	  }
408	
409	  function renderSessionMeta() {
410	    const session = state.open;
411	    if (!session) return;
412	    $('session-meta').textContent = [session.kind, session.card].filter(Boolean).join(' · ');
413	    const waiting = $('session-waiting');
414	    waiting.hidden = !session.waiting;
415	    waiting.textContent = session.waiting_reason
416	      ? `Waiting on you: ${session.waiting_reason}`
417	      : 'Waiting on you';
418	    const canSend = state.me && state.me.scope === 'control' && !session.prompt_refusal;
419	    $('reply').hidden = !canSend;
420	    const refusal = $('refusal');
421	    refusal.hidden = !(state.me && state.me.scope === 'control' && session.prompt_refusal);
422	    refusal.textContent = session.prompt_refusal ? `No reply: ${session.prompt_refusal}` : '';
423	  }
424	
425	  async function refreshSession() {
426	    const session = state.open;
427	    if (!session) return;
428	    const path = session.kind === 'claude' ? API.lastResponse : API.screen;
429	    const reply = await read(path.replace('{id}', session.id));
430	    if (!reply || state.open !== session) return;
431	    if (reply.status !== 200) {
432	      const message = reply.json && reply.json.error ? reply.json.error.message : `HTTP ${reply.status}`;
433	      $('session-text').textContent = message;
434	      return;
435	    }
436	    if (state.openView && !accepts(state.openView, reply.json)) return;
437	    state.openView = { epoch: reply.json.epoch, revision: reply.json.revision };
438	    $('session-text').textContent = reply.json.body.text || '';
439	    $('session-truncated').hidden = !reply.json.body.truncated;
440	  }
441	
442	  // The session as the list now says it is, so the card word and the
443	  // refusal follow a refetch.
444	  function syncOpenFromList() {
445	    if (!state.open) return;
446	    for (const group of state.groups) {
447	      const found = group.sessions.find((s) => s.id === state.open.id);
448	      if (found) {
449	        state.open = found;
450	        renderSessionMeta();
451	        return;
452	      }
453	    }
454	  }
455	
456	  async function send(event) {
457	    event.preventDefault();
458	    const session = state.open;
459	    const text = $('reply-text').value;
460	    if (!session || !text.trim()) return;
461	    if (!state.pendingOp) state.pendingOp = newOp((b) => crypto.getRandomValues(b));
462	    const op = state.pendingOp;
463	    $('send').disabled = true;
464	    $('send-status').textContent = 'Sending…';
465	    const reply = await api('POST', API.send.replace('{id}', session.id), { op, text });
466	    $('send').disabled = false;
467	    if (reply.status === 401) {
468	      await unauthorized();
469	      return;
470	    }
471	    if (reply.status === 0) {
472	      $('send-status').textContent = 'No answer; Send again repeats the same operation.';
473	      return;
474	    }
475	    const code = errorCode(reply);
476	    if (reply.status === 403 && code === 'scope') {
477	      $('send-status').textContent = 'This device reads only now.';
478	      await refreshMe();
479	      renderSessionMeta();
480	      return;
481	    }
482	    if (reply.status !== 200) {
483	      const message = reply.json && reply.json.error ? reply.json.error.message : `HTTP ${reply.status}`;
484	      $('send-status').textContent = message;
485	      state.pendingOp = null;
486	      return;
487	    }
488	    state.pendingOp = null;
489	    $('reply-text').value = '';
490	    $('send-status').textContent = 'Sent';
491	  }
492	
493	  // --- refresh: polling as the base, the socket as the enhancement
494	
495	  async function refreshAll() {
496	    await refreshList();
497	    syncOpenFromList();
498	    await refreshSession();
499	  }
500	
501	  async function poll() {
502	    if (document.hidden) return;
503	    const reply = await read(API.waiting);
504	    if (!reply || reply.status !== 200) return;
505	    const seen = { epoch: reply.json.epoch, revision: reply.json.revision };
506	    if (state.held && state.held.epoch === seen.epoch && state.held.revision === seen.revision) {
507	      return;
508	    }
509	    state.held = seen;
510	    await refreshAll();
511	  }
512	
513	  function startRefresh() {
514	    stopRefresh();
515	    state.pollTimer = setInterval(poll, state.pollMs);
516	    openSocket();
517	  }
518	
519	  function stopRefresh() {
520	    if (state.pollTimer) clearInterval(state.pollTimer);
521	    state.pollTimer = null;
522	    if (state.socket) {
523	      const socket = state.socket;
524	      state.socket = null;
525	      socket.onclose = null;
526	      socket.close();
527	    }
528	  }
529	
530	  function setPoll(ms) {
531	    if (state.pollMs === ms && state.pollTimer) return;
532	    state.pollMs = ms;
533	    if (state.pollTimer) clearInterval(state.pollTimer);
534	    state.pollTimer = setInterval(poll, ms);
535	  }
536	
537	  function openSocket() {
538	    if (state.socket || typeof WebSocket === 'undefined') return;
539	    let socket;
540	    try {
541	      socket = new WebSocket(`wss://${location.host}${API.events}`);
542	    } catch (e) {
543	      return;
544	    }
545	    state.socket = socket;
546	    socket.onopen = () => {
547	      state.socketRetryMs = SOCKET_RETRY_MS;
548	      setPoll(POLL_SLOW_MS);
549	    };
550	    socket.onmessage = (message) => {
551	      let frame;
552	      try {
553	        frame = JSON.parse(message.data);
554	      } catch (e) {
555	        return;
556	      }
557	      if (frame.type === 'changed' || frame.type === 'removed') {
558	        refreshAll();
559	      } else if (frame.type === 'resync_required') {
560	        refreshAll();
561	      }
562	    };
563	    socket.onerror = () => {};
564	    socket.onclose = () => {
565	      if (state.socket !== socket) return;
566	      state.socket = null;
567	      setPoll(POLL_MS);
568	      refreshAll();
569	      const wait = state.socketRetryMs;
570	      state.socketRetryMs = Math.min(wait * 2, SOCKET_RETRY_MAX_MS);
571	      setTimeout(() => {
572	        if (state.pollTimer) openSocket();
573	      }, wait);
574	    };
575	  }
576	
577	  document.addEventListener('visibilitychange', () => {
578	    if (!document.hidden && state.pollTimer) poll();
579	  });
580	  $('back').addEventListener('click', () => {
581	    state.open = null;
582	    state.openView = null;
583	    show('list');
584	  });
585	  $('reply').addEventListener('submit', send);
586	  boot();
587	}
588

