1	//! The remote port's state: the host's identity, the devices paired
2	//! with it, and the pairing window. Random material (the code, a
3	//! token) is made outside and arrives in the action; here it is only
4	//! compared and kept, so every transition is a plain function of its
5	//! inputs.
6	
7	use std::net::{IpAddr, SocketAddr};
8	use std::time::SystemTime;
9	
10	use uuid::Uuid;
11	
12	use super::action::PairingWindow;
13	use super::action::{AppAction, AppCore, Clock, Effect, Out, PAIRING_ATTEMPTS, PAIRING_WINDOW};
14	use crate::ports::remote::{Identity, PairedDevice, Scope};
15	
16	/// A device's last-seen time is saved when it moved by at least this
17	/// much, so a polling device does not rewrite `devices.json` on every
18	/// request.
19	const LAST_SEEN_SAVE_INTERVAL_SECS: u64 = 300;
20	
21	/// The URL the pairing window's QR code carries, which a phone's
22	/// browser opens: the page at the port, with the code, the key hash and
23	/// the server id in the fragment. A fragment is never sent in the
24	/// request, so a server the owner has not verified never sees the code
25	/// before the page compares the key. `address` is where the port
26	/// answers on the network; `None` when it answers this Mac alone, in
27	/// which case the URL names the loopback address.
28	#[must_use]
29	pub fn invite_url(
30	    identity: &Identity,
31	    window: &PairingWindow,
32	    address: Option<IpAddr>,
33	    port: u16,
34	) -> String {
35	    let at = SocketAddr::new(address.unwrap_or(IpAddr::from([127, 0, 0, 1])), port);
36	    format!(
37	        "https://{at}/#code={}&key={}&id={}",
38	        window.code, identity.spki_sha256, identity.server_id
39	    )
40	}
41	
42	impl AppCore {
43	    pub(super) fn remote_action(&mut self, action: AppAction, now: Clock, out: &mut Out) {
44	        match action {
45	            AppAction::IdentityLoaded {
46	                identity,
47	                devices,
48	                rotated,
49	            } => {
50	                self.identity = Some(identity);
51	                self.devices = devices;
52	                self.identity_rotated_at = rotated.then_some(now.mono);
53	            }
54	            AppAction::SetServerName(name) => {
55	                let name = name.trim().to_owned();
56	                if !name.is_empty() {
57	                    self.update_identity(out, |i| i.server_name = name);
58	                }
59	            }
60	            AppAction::SetRemoteListen { lan, port } => {
61	                if port != 0 {
62	                    self.update_identity(out, |i| {
63	                        i.listen.lan = lan;
64	                        i.listen.port = port;
65	                    });
66	                }
67	            }
68	            AppAction::OpenPairing { code, scope } => {
69	                // Typed by hand on the device, so case never matters.
70	                self.pairing = Some(PairingWindow {
71	                    until: now.mono + PAIRING_WINDOW,
72	                    code: code.trim().to_ascii_uppercase(),
73	                    scope,
74	                    failures: 0,
75	                });
76	            }
77	            AppAction::ClosePairing => self.pairing = None,
78	            AppAction::PairingFailed => {
79	                if let Some(p) = &mut self.pairing {
80	                    p.failures += 1;
81	                    if p.failures >= PAIRING_ATTEMPTS {
82	                        self.pairing = None;
83	                        self.error("Pairing closed: three attempts failed.");
84	                    }
85	                }
86	            }
87	            AppAction::Paired(device) => {
88	                // The code is single-use: the window closes with the
89	                // first pairing made through it.
90	                self.pairing = None;
91	                self.devices.push(device);
92	                self.save_devices(out);
93	            }
94	            AppAction::DeviceSeen(id) => {
95	                let Some(device) = self.devices.iter_mut().find(|d| d.id == id) else {
96	                    return;
97	                };
98	                let stale = device.last_seen.is_none_or(|seen| {
99	                    now.wall
100	                        .duration_since(seen)
101	                        .is_ok_and(|d| d.as_secs() >= LAST_SEEN_SAVE_INTERVAL_SECS)
102	                });
103	                device.last_seen = Some(now.wall);
