'use strict';

// The page's pure parts under `node --test`; `tests/remote.rs` runs
// this and skips when node is absent.

const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('./app.js');

test('the fragment carries the code, the key and the id, or nothing', () => {
  assert.deepEqual(app.parseFragment('#code=ABCD2345&key=ab&id=17a9'), {
    code: 'ABCD2345',
    key: 'ab',
    id: '17a9',
  });
  assert.equal(app.parseFragment('#code=ABCD2345&key=ab'), null);
  assert.equal(app.parseFragment(''), null);
  assert.equal(app.parseFragment('#'), null);
  assert.equal(app.parseFragment('#code=&key=ab&id=1'), null);
  assert.equal(app.parseFragment('#key=ab&id=1&code=X%20Y').code, 'X Y');
});

test('the device name is the browser on the device', () => {
