test('a reply applies at or past the held revision, and always on a new epoch', () => {
  const held = { epoch: 'e', revision: 10 };
  assert.equal(app.accepts(null, { epoch: 'e', revision: 1 }), true);
  assert.equal(app.accepts(held, { epoch: 'e', revision: 10 }), true);
  assert.equal(app.accepts(held, { epoch: 'e', revision: 11 }), true);
  assert.equal(app.accepts(held, { epoch: 'e', revision: 9 }), false);
  assert.equal(app.accepts(held, { epoch: 'f', revision: 0 }), true);
});

test('waiting sessions and their projects come first', () => {
  const projects = [
    { id: 'p1', name: 'alpha' },
    { id: 'p2', name: 'beta' },
  ];
  const sessions = {
    p1: [
      { id: 's1', name: 'one', waiting: false, last_activity_ms: 50 },
      { id: 's2', name: 'two', waiting: false, last_activity_ms: 90 },
    ],
    p2: [
      { id: 's3', name: 'three', waiting: false, last_activity_ms: 10 },
      { id: 's4', name: 'four', waiting: true, last_activity_ms: null },
    ],
  };
  const groups = app.orderList(projects, sessions);
  assert.deepEqual(groups.map((g) => g.project.id), ['p2', 'p1']);
  assert.deepEqual(groups[0].sessions.map((s) => s.id), ['s4', 's3']);
  assert.deepEqual(groups[1].sessions.map((s) => s.id), ['s2', 's1']);
  assert.deepEqual(app.orderList([{ id: 'p', name: 'x' }], {})[0].sessions, []);
});

test('time since reads in words', () => {
  const now = 1_000_000_000;
  assert.equal(app.sinceText(null, now), '');
  assert.equal(app.sinceText(now - 5_000, now), 'just now');
  assert.equal(app.sinceText(now - 180_000, now), '3 m ago');
  assert.equal(app.sinceText(now - 7_200_000, now), '2 h ago');
  assert.equal(app.sinceText(now - 3 * 86_400_000, now), '3 d ago');
});

