/// Where the pairing invite points a phone. The dialog shows it and
/// the URL is built from it, so the address line and the QR code
/// cannot disagree.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InviteAddress {
    /// The port listens on the network and this Mac has this address
    /// on it: what a phone reaches.
    Network(SocketAddr),
    /// The port listens on the network but this Mac has no address on
    /// one (no network is up), so the loopback address stands in,
    /// which no phone reaches.
    NoNetwork(SocketAddr),
    /// The port answers this Mac alone, at the loopback address.
    MacOnly(SocketAddr),
}

impl InviteAddress {
    /// The address the URL names, whichever case it is.
    #[must_use]
    pub fn socket(self) -> SocketAddr {
        match self {
            Self::Network(at) | Self::NoNetwork(at) | Self::MacOnly(at) => at,
        }
    }
}

/// The invite's address from how the port listens: the Mac's network
/// address only while the port listens on the network, and loopback
/// otherwise. `local` finds that address and is asked only when it
/// matters, so the core decides and the caller does the looking.
#[must_use]
pub fn invite_address(
    identity: &Identity,
    port: u16,
    local: impl FnOnce() -> Option<IpAddr>,
) -> InviteAddress {
    let loopback = SocketAddr::new(IpAddr::from([127, 0, 0, 1]), port);
    if !identity.listen.lan {
        return InviteAddress::MacOnly(loopback);
    }
    match local() {
        Some(ip) => InviteAddress::Network(SocketAddr::new(ip, port)),
        None => InviteAddress::NoNetwork(loopback),
    }
}

