/// before the page compares the key.
#[must_use]
pub fn invite_url(identity: &Identity, window: &PairingWindow, address: InviteAddress) -> String {
    format!(
        "https://{}/#code={}&key={}&id={}",
        address.socket(),
        window.code,
        identity.spki_sha256,
        identity.server_id
    )
}

