/// The invite is a URL to the page with the code, key and id in its
/// fragment, never in a query: the code is never sent to whoever
/// answers the address. The address is the Mac's network address
/// only while the port listens on the network, and the loopback
/// address otherwise, each case told apart for the dialog.
#[test]
fn the_invite_url_carries_the_code_in_its_fragment() {
    use std::net::{IpAddr, SocketAddr};

    use crate::core::{InviteAddress, invite_address, invite_url};
    let mut core = loaded_core();
    core.dispatch(
        AppAction::OpenPairing {
            code: "abcd2345".into(),
            scope: Scope::Read,
        },
        Clock::at(0),
    );
    core.dispatch(
        AppAction::SetRemoteListen {
            lan: true,
            port: 43187,
        },
        Clock::at(0),
    );
    let identity = core.identity().unwrap();
    let window = core.pairing().unwrap();
    let lan = IpAddr::from([192, 168, 1, 9]);
    let address = invite_address(identity, 43187, || Some(lan));
    assert_eq!(
        address,
        InviteAddress::Network(SocketAddr::new(lan, 43187))
    );
    let url = invite_url(identity, window, address);
    assert_eq!(
        url,
        format!(
            "https://192.168.1.9:43187/#code=ABCD2345&key={}&id={}",
            identity.spki_sha256, identity.server_id
        )
    );
    assert!(!url.contains('?'), "nothing of the invite is a query");
    let six = invite_address(identity, 5000, || Some(IpAddr::from([0, 0, 0, 0, 0, 0, 0, 1])));
    assert!(
        invite_url(identity, window, six).starts_with("https://[::1]:5000/#"),
        "{six:?}"
    );
    let loopback: SocketAddr = "127.0.0.1:5000".parse().unwrap();
    let no_network = invite_address(identity, 5000, || None);
    assert_eq!(no_network, InviteAddress::NoNetwork(loopback));
    assert!(
        invite_url(identity, window, no_network).starts_with("https://127.0.0.1:5000/#code="),
        "{no_network:?}"
    );

    core.dispatch(
        AppAction::SetRemoteListen {
            lan: false,
            port: 5000,
        },
        Clock::at(1),
    );
    let identity = core.identity().unwrap();
    let mac_only = invite_address(identity, 5000, || {
        unreachable!("the address is not looked for while the port is this Mac's alone")
    });
    assert_eq!(mac_only, InviteAddress::MacOnly(loopback));
    assert!(
        invite_url(identity, window, mac_only).starts_with("https://127.0.0.1:5000/#code="),
        "{mac_only:?}"
    );
}

