fn record(project: ProjectId, kind: SessionKind, order: u32) -> SessionRecord {
    let t = Clock::at(0).wall;
    SessionRecord {
        id: RecordId::new(),
        project,
        name: format!("s{order}"),
        kind,
        cwd: PathBuf::from("/tmp/proj"),
