    }
}

fn read_diff(path: &str, range: &DiffRange) -> AppAction {
    AppAction::ReadFileDiff {
        ticket: "t1".into(),
        lane: "repo".into(),
        path: path.into(),
        old_path: None,
        range: range.clone(),
    }
}

fn diff_read(path: &str, range: &DiffRange, result: Result<FileDiff, String>) -> AppAction {
    AppAction::FileDiffRead {
        ticket: "t1".into(),
        lane: "repo".into(),
        path: path.into(),
