fn the_config_files_show_list_lands_on_the_project_record() {
    let (mut core, pid, _) = with_records(&[], |_| None);
    let mut cfg = ProjectConfig {
        shell: "/bin/zsh".into(),
        show: vec![PathBuf::from("manager")],
        ..ProjectConfig::default()
    };
    let e = core.dispatch(
        AppAction::ProjectConfigRead {
