    assert_eq!(saves(&e), 1);
    assert_eq!(
        core.workspace(pid).unwrap().project.shown,
        [PathBuf::from("manager")]
    );
    // The same list again is not a change; an unreadable file keeps it;
    // a removed file clears it.
    let e = core.dispatch(
        AppAction::ProjectConfigRead {
            project: pid,
            result: Ok(Some(cfg.clone())),
        },
        Clock::at(2),
    );
    assert_eq!(saves(&e), 0);
