        AppAction::ProjectConfigRead {
            project: pid,
            result: Err("unreadable".into()),
        },
        Clock::at(3),
    );
    assert_eq!(saves(&e), 0);
    assert_eq!(core.workspace(pid).unwrap().project.shown.len(), 1);
    let e = core.dispatch(
        AppAction::ProjectConfigRead {
            project: pid,
            result: Ok(None),
        },
        Clock::at(4),
