fn config(entries: Vec<DefinedEntry>) -> Result<Option<ProjectConfig>, String> {
    Ok(Some(ProjectConfig {
        entries,
        warnings: vec![],
        shell: "/bin/zsh".into(),
        show: vec![],
    }))
}

