        .unwrap_or_else(|| panic!("no record {name}"))
        .clone()
}

#[test]
fn project_config_read_adds_pending_records_once() {
    let (mut core, pid, _) = with_records(&[], |_| None);
    let entries = vec![
        entry("lint", SessionKind::Command, "cargo clippy"),
        DefinedEntry {
            cwd: Some("web".into()),
