    }

    #[test]
    fn the_users_own_feedback_is_a_round_for_the_planner_only() {
        let (mut core, run, _, _, planner) = started();
        settle(&mut core, run, "No further feedback.", 400);
        core.dispatch(
            AppAction::HostListed(vec![running(planner)]),
