        );
        let r = run_of(&core);
        assert_eq!(r.state, RunState::Finalized);
        assert_eq!(r.rounds.len(), 1);
        assert!(sent(&effects).is_empty(), "no planner prompt");
        let n = core.notices.last().unwrap();
        assert!(n.is_error);
        assert!(n.text.contains("Dispatch: reviewer@gone"), "{}", n.text);
    }

