    assert_eq!(core.take_ui_requests(), vec![UiRequest::Terminal(agent_id)]);
    assert!(core.take_ui_requests().is_empty(), "taken once");
    // Down is Stop: Escape to the pane.
    press(&mut core, Button::Z, true, 12000);
