        assert_eq!(error, None);
        assert_eq!(kills(&e), 1);
        assert_eq!(spawns(&e, id), 0, "the old runner may still hold the lock");
        assert_eq!(core.runner_standing(), RunnerStanding::StartQueued);
        let saved = saved_autostart(&e, id);
