#[test]
fn the_session_view_says_what_the_stop_listed_and_until_when_it_holds() {
    let (mut core, _, ids) = with_records(&[agent()], |s| Some(running(s.id)));
    let id = ids[0];
    let view = core.session_view(id, Clock::at(1_000).wall).unwrap();
    assert!(view.pending.is_empty());
    assert_eq!((view.wakeup_at_ms, view.held_until_ms), (None, None));
    core.dispatch(
        AppAction::Events(vec![SessionEvent {
            record_id: Some(id),
            ..event(
                EventKind::Stopped {
                    last_message: None,
                    pending: Some(StopPending {
                        tasks: vec!["shell".into()],
                        wakeups: vec![
                            wakeup_at(90_000),
                            Wakeup {
                                fire_at: None,
                                recurring: true,
                            },
                        ],
                    }),
                },
                2_000,
            )
        }]),
        Clock::at(2_000),
    );
    let view = core.session_view(id, Clock::at(3_000).wall).unwrap();
    assert_eq!(view.pending, ["shell", "wakeup", "recurring wakeup"]);
    let ms =
        |t: SystemTime| u64::try_from(t.duration_since(UNIX_EPOCH).unwrap().as_millis()).unwrap();
    assert_eq!(view.wakeup_at_ms, Some(ms(Clock::at(90_000).wall)));
    assert_eq!(
        view.held_until_ms,
        Some(ms(Clock::at(2_000).wall + BACKGROUND_HOLD))
    );
    assert_eq!(core.state_text(id), "idle: 3 pending");
    assert_eq!(view.card, CardState::Idle.label());
}

#[test]
fn a_stop_is_remembered_on_its_own_and_an_outside_wait_reads_as_waiting() {
    let (mut core, _, ids) = with_records(&[agent()], |s| Some(running(s.id)));
    let id = ids[0];
    assert_eq!(core.session(id).unwrap().last_stop_at, None);
    core.dispatch(
        AppAction::Events(vec![SessionEvent {
            record_id: Some(id),
            ..event(EventKind::PromptSubmitted, 100)
        }]),
        Clock::at(1),
    );
    // Any event moves `last_event_at`; only a stop moves `last_stop_at`.
    assert_eq!(core.session(id).unwrap().last_stop_at, None);
    core.dispatch(
        AppAction::Events(vec![SessionEvent {
            record_id: Some(id),
            // A second later: the wall clock is whole seconds.
            ..event(
                EventKind::Stopped {
                    last_message: None,
                    pending: None,
                },
                2_100,
            )
        }]),
        Clock::at(1),
    );
    assert_eq!(
        core.session(id).unwrap().last_stop_at,
        Some(Clock::at(2_100).wall)
    );
    assert_eq!(core.card_state(id), CardState::Idle);
    // Someone outside (Dispatch) says a decision waits on this session:
    // the card reads as waiting while the pane runs, whatever the hooks
    // last said.
    core.seed_waiting_on(id, Some("finalize the review?".into()));
    assert_eq!(core.card_state(id), CardState::WaitingOnYou);
    assert_eq!(core.waiting_count(), 1);
    core.seed_waiting_on(id, None);
    assert_eq!(core.card_state(id), CardState::Idle);
}

