fn a_new_session_id_from_the_pane_rebinds_the_record_after_clear() {
    let p = project("p");
    let mut w = Workspace::new(p.clone());
    let mut r = record(p.id, agent(), 0);
    let old = Uuid::new_v4();
    r.resume = Some(ResumeHandle::ClaudeCode {
