                    y: 0,
                    w: 10,
                    h: 8,
                },
            },
        ],
        op: None,
        rule: None,
        dismissed: Vec::new(),
        running_only: false,
        card_scale: crate::core::WorkingSet::default_card_scale(),
    });
    let load = |last_view: SavedView| {
        let mut core = AppCore::new();
        let effects = core.dispatch(
            AppAction::StoreLoaded(Ok(Loaded {
                workspaces: vec![w.clone()],
                settings: Settings {
                    last_view,
                    ..Settings::default()
                },
                views: views.clone(),
                ..Loaded::default()
            })),
            Clock::at(0),
