#[test]
fn widening_the_hours_brings_back_quiet_sessions() {
    let (mut core, _, ids) = with_records(&[SessionKind::Shell], |_| None);
    let set = recent_set(&mut core, 1, 1_000);
    tick(&mut core, 2 * HOUR_MS);
