    assert_eq!(members(&core, set), vec![ids[0]]);
    let hours = |core: &AppCore| core.working_set(set).unwrap().rule;
    for (asked, kept) in [(0, 1), (10_000, 720), (48, 48)] {
        core.dispatch(
            AppAction::SetRuleHours { set, hours: asked },
            Clock::at(2 * HOUR_MS),
