// --- the control port: quiet commands under an operation id

mod control {
    use super::*;
    use crate::core::{
        ControlAction, PinnedItem, RunState, SetId, WorkflowDefinition, WorkflowId, WorkingSet,
    };
    use switchboard_control::RecordKind;

    fn control(core: &mut AppCore, op: &str, action: ControlAction, at: u64) -> Vec<Effect> {
        core.dispatch(
            AppAction::Control {
                op: op.into(),
                action,
            },
            Clock::at(at),
        )
    }

    fn new_session_op(project: ProjectId, prompt: Option<&str>) -> ControlAction {
        ControlAction::NewSession {
            project,
            name: "investigator".into(),
            kind: agent(),
            cwd: "/tmp/proj".into(),
            launch: Launch::Shell,
            prompt: prompt.map(str::to_owned),
            notes: "Dispatch ticket 1, stage investigate".into(),
            env: BTreeMap::new(),
            env_sets: Vec::new(),
            replaces: None,
        }
    }

    fn at(x: u32) -> GridRect {
        GridRect {
            x,
            y: 0,
            w: 10,
            h: 8,
        }
    }

    fn hand_set(space: SpaceId, pins: &[(RecordId, GridRect)]) -> WorkingSet {
        WorkingSet {
            space,
            items: pins
                .iter()
                .map(|(id, rect)| PinnedItem {
                    target: PinTarget::Session(*id),
                    rect: *rect,
                })
                .collect(),
            ..WorkingSet::default()
        }
    }

    fn save_views(effects: &[Effect]) -> usize {
        effects
            .iter()
            .filter(|e| matches!(e, Effect::SaveViews(_)))
            .count()
    }

    /// A Fresh supervisor's card lands where the old one was pinned,
    /// and nothing else on any set moves.
    #[test]
    fn a_new_session_that_replaces_another_takes_its_pins_in_place() {
        let (mut core, pid, ids) = with_records(&[agent(), SessionKind::Shell], |_| None);
        let [old, x] = [ids[0], ids[1]];
        let a = hand_set(SpaceId::DEFAULT, &[(old, at(0)), (x, at(10))]);
        let rule = WorkingSet {
            rule: Some(SetRule::Recent { hours: 24 }),
            dismissed: vec![crate::core::Dismissal {
                record: old,
                at: SystemTime::UNIX_EPOCH,
            }],
            ..WorkingSet::default()
        };
        core.seed_views(Views {
            sets: vec![a.clone(), rule.clone()],
            ..Views::default()
        });
        let mut op = new_session_op(pid, None);
        if let ControlAction::NewSession { replaces, .. } = &mut op {
            *replaces = Some(old);
        }
        let effects = control(&mut core, "op-1", op, 10);
        let new = core
            .workspace(pid)
            .unwrap()
            .sessions
            .iter()
            .find(|s| s.name == "investigator")
            .map(|s| s.id)
            .unwrap();
        let after = core.working_set(a.id).unwrap();
        assert_eq!(
            after.items,
            vec![
                PinnedItem {
                    target: PinTarget::Session(new),
                    rect: at(0),
                },
                PinnedItem {
                    target: PinTarget::Session(x),
                    rect: at(10),
                },
            ]
        );
        assert_eq!(core.working_set(rule.id), Some(&rule));
        assert_eq!(save_views(&effects), 1, "{effects:?}");
    }

    #[test]
    fn a_takeover_into_a_set_that_already_pins_the_successor_drops_the_old_card() {
        let (mut core, _, ids) = with_records(&[agent(), agent()], |_| None);
        let [a, b] = [ids[0], ids[1]];
        let set_a = hand_set(SpaceId::DEFAULT, &[(a, at(0))]);
        let set_b = hand_set(SpaceId::DEFAULT, &[(a, at(0)), (b, at(10))]);
        core.seed_views(Views {
            sets: vec![set_a.clone(), set_b.clone()],
            ..Views::default()
        });
        let mut out = crate::core::action::Out::default();
        core.take_over_pins(a, b, &mut out);
        assert_eq!(
            core.working_set(set_b.id).unwrap().items,
            vec![PinnedItem {
                target: PinTarget::Session(b),
                rect: at(10),
            }]
        );
        assert_eq!(
            core.working_set(set_a.id).unwrap().items,
            vec![PinnedItem {
                target: PinTarget::Session(b),
                rect: at(0),
            }]
        );
    }

    /// A successor outside a set's space would be pruned off it, so the
    /// old card stays where it is.
    #[test]
    fn a_takeover_leaves_a_set_of_another_space_alone() {
        let (mut core, b_space, _, [in_default, in_b]) = two_spaces();
        let set = hand_set(b_space, &[(in_b, at(0))]);
        core.seed_views(Views {
            sets: vec![set.clone()],
            ..core.views.clone()
        });
        let mut out = crate::core::action::Out::default();
        core.take_over_pins(in_b, in_default, &mut out);
        assert_eq!(core.working_set(set.id), Some(&set));
    }

    #[test]
    fn a_new_session_without_replaces_leaves_the_views_alone() {
        let (mut core, pid, ids) = with_records(&[agent()], |_| None);
        core.seed_views(Views {
            sets: vec![hand_set(SpaceId::DEFAULT, &[(ids[0], at(0))])],
            ..Views::default()
        });
        let before = core.views.clone();
        let effects = control(&mut core, "op-1", new_session_op(pid, None), 10);
        assert_eq!(core.views, before);
        assert_eq!(save_views(&effects), 0, "{effects:?}");
    }

    /// A launcher's variables land on the record, where every spawn
    /// reads them; a clone of that session is a new attempt and starts
    /// with none.
    #[test]
    fn a_port_sessions_env_lands_on_its_record_and_a_clone_starts_with_none() {
        let (mut core, pid, _) = with_records(&[], |_| None);
        let env = BTreeMap::from([(
            "DISPATCH_INPUT_PERSONAS".to_owned(),
            "/d/personas.md".to_owned(),
        )]);
        let mut op = new_session_op(pid, Some("Try it"));
        if let ControlAction::NewSession { env: e, .. } = &mut op {
            *e = env;
        }
        control(&mut core, "op-1", op, 10);
        let made = core
            .workspace(pid)
            .unwrap()
            .sessions
            .iter()
            .find(|s| s.name == "investigator")
            .map(|s| s.id)
            .unwrap();
        assert_eq!(
            core.session(made).unwrap().env,
            [(
                "DISPATCH_INPUT_PERSONAS".to_owned(),
                "/d/personas.md".to_owned()
            )]
        );
        // A source with variables of its own.
        let p = project("p");
        let mut w = Workspace::new(p.clone());
        let mut r = record(p.id, agent(), 0);
        r.resume = Some(claude_handle());
        r.env = vec![("DISPATCH_INPUT_PLAN".into(), "/d/plan.md".into())];
        let source = r.id;
        w.sessions.push(r);
        let (mut core, _) = loaded(vec![w], vec![]);
        control(
            &mut core,
            "op-3",
            ControlAction::CloneSession {
                source,
                name: "rebaser".into(),
                prompt: "Rebase.".into(),
                notes: String::new(),
                env_sets: Vec::new(),
            },
            12,
        );
        let clone = core
            .workspace(p.id)
            .unwrap()
            .sessions
            .iter()
            .find(|s| s.name == "rebaser")
            .expect("the clone's record");
        assert!(clone.env.is_empty(), "{:?}", clone.env);
    }

    /// The port's resume of a running pane leaves it as it is: the
    /// quiet port never opens a terminal.
    #[test]
    fn a_port_resume_of_a_running_session_does_nothing() {
        let (mut core, id) = resumable_agent();
        core.dispatch(AppAction::HostListed(vec![running(id)]), Clock::at(2));
        let effects = control(&mut core, "op-r", ControlAction::Resume(id), 3);
        assert!(
            !effects.iter().any(|e| matches!(e, Effect::Attach { .. })),
            "{effects:?}"
        );
        assert!(
            !effects
                .iter()
                .any(|e| matches!(e, Effect::CheckTranscript { .. } | Effect::Spawn { .. })),
            "{effects:?}"
        );
        assert_eq!(core.take_control_outcome("op-r").unwrap().error, None);
    }

    #[test]
    fn a_port_resume_of_a_cold_agent_starts_the_preflight() {
        let (mut core, id) = resumable_agent();
        let effects = control(&mut core, "op-r", ControlAction::Resume(id), 3);
        assert!(
            effects
                .iter()
                .any(|e| matches!(e, Effect::CheckTranscript { id: i, .. } if *i == id)),
            "{effects:?}"
        );
        assert_eq!(core.take_control_outcome("op-r").unwrap().error, None);
    }

    /// Never a fresh launch: that would run the first prompt again.
    #[test]
    fn a_port_resume_of_a_session_that_cannot_resume_is_refused() {
        for no_handle in [false, true] {
            let p = project("p");
            let mut w = Workspace::new(p.clone());
            let mut r = record(p.id, agent(), 0);
            if no_handle {
                r.resume = None;
            } else {
                r.resume = Some(claude_handle());
                r.not_resumable = true;
            }
            let id = r.id;
            w.sessions.push(r);
            let (mut core, _) = loaded(vec![w], vec![]);
            let effects = control(&mut core, "op-r", ControlAction::Resume(id), 3);
            assert!(
                !effects.iter().any(|e| matches!(
                    e,
                    Effect::CheckTranscript { .. }
                        | Effect::Spawn { .. }
                        | Effect::PrepareLaunch { .. }
                )),
                "{effects:?}"
            );
            let error = core.take_control_outcome("op-r").unwrap().error.unwrap();
            assert!(error.contains("not resumable"), "{error}");
        }
    }

    /// `session.clone` makes the record at once, so the asker has its
    /// id and its op, and launches it through the copied transcript.
    #[test]
    fn a_session_cloned_by_the_port_exists_before_its_copy_and_launches_from_it() {
        let (mut core, source) = resumable_agent();
        let pid = core.session(source).unwrap().project;
        let effects = control(
            &mut core,
            "op-9",
            ControlAction::CloneSession {
                source,
                name: "rebaser".into(),
                prompt: "Rebase onto main.".into(),
                notes: "Dispatch ticket 1, rebase".into(),
                env_sets: Vec::new(),
            },
            10,
        );
        let outcome = core.take_control_outcome("op-9").expect("an outcome");
        assert_eq!(outcome.error, None);
        assert_eq!(outcome.made.len(), 1);
        let id = core
            .workspace(pid)
            .unwrap()
            .sessions
            .iter()
            .find(|s| s.name == "rebaser")
            .map(|s| s.id)
            .expect("the clone's record");
        assert_eq!(outcome.made[0].id, id.0.to_string());
        let record = core.session(id).unwrap();
        assert_eq!(record.op.as_deref(), Some("op-9"));
        assert_eq!(record.notes, "Dispatch ticket 1, rebase");
        assert!(record.pending_launch);
        assert_eq!(record.resume, None, "no handle until the copy exists");
        assert_eq!(record.cwd, core.session(source).unwrap().cwd);
        assert!(
            effects
                .iter()
                .any(|e| matches!(e, Effect::CloneTranscriptInto { target, .. } if *target == id)),
            "{effects:?}"
        );
        let copy = claude_handle();
        let effects = core.dispatch(
            AppAction::TranscriptClonedInto {
                target: id,
                prompt: "Rebase onto main.".into(),
                result: Ok(copy.clone()),
            },
            Clock::at(11),
        );
        assert_eq!(core.session(id).unwrap().resume, Some(copy));
        assert!(
            effects
                .iter()
                .any(|e| matches!(e, Effect::CheckTranscript { id: i, .. } if *i == id)),
            "the record resumes through the copy: {effects:?}"
        );
        // A copy that could not be made leaves a record that never ran.
        let effects = control(
            &mut core,
            "op-10",
            ControlAction::CloneSession {
                source,
                name: "rebaser".into(),
                prompt: "again".into(),
                notes: String::new(),
                env_sets: Vec::new(),
            },
            12,
        );
        let second = match &effects[0] {
            Effect::LogOperation { ids, .. } => ids[0].parse::<Uuid>().map(RecordId).unwrap(),
            other => panic!("{other:?}"),
        };
        core.dispatch(
            AppAction::TranscriptClonedInto {
                target: second,
                prompt: "again".into(),
                result: Err("no transcript".into()),
            },
            Clock::at(13),
        );
        let record = core.session(second).unwrap();
        assert!(record.not_resumable && !record.pending_launch);
    }

    #[test]
    fn a_session_made_by_the_port_carries_its_op_and_moves_nothing_on_screen() {
        let (mut core, pid, _) = with_records(&[], |_| None);
        core.dispatch(AppAction::ShowSwitchboard, Clock::at(1));
        core.dispatch(AppAction::SetOpenTerminalOnLaunch(true), Clock::at(2));
        let view = core.view();
        let effects = control(
            &mut core,
            "op-1",
            new_session_op(pid, Some("Investigate #1")),
            10,
        );
        // The log line leads, the save follows, then the launch.
        assert!(
            matches!(&effects[0], Effect::LogOperation { op, kind, ids } if op == "op-1" && kind == "session.new" && ids.len() == 1),
            "{effects:?}"
        );
        assert!(matches!(&effects[1], Effect::Save(_)));
        let outcome = core.take_control_outcome("op-1").expect("an outcome");
        assert_eq!(outcome.error, None);
        assert_eq!(outcome.made.len(), 1);
        assert_eq!(outcome.made[0].kind, RecordKind::Session);
        let id = core.workspace(pid).unwrap().sessions[0].id;
        assert_eq!(outcome.made[0].id, id.0.to_string());
        let record = core.session(id).unwrap();
        assert_eq!(record.op.as_deref(), Some("op-1"));
        assert_eq!(record.notes, "Dispatch ticket 1, stage investigate");
        // The pending mark is in the saved record, before the launch.
        assert!(record.pending_launch);
        assert!(matches!(&effects[1], Effect::Save(w) if w.sessions[0].pending_launch));
        assert_eq!(core.view(), view);
        assert!(core.notice().is_none());
        // The first prompt rides on the command line, and no terminal
        // window opens for a session another process asked for.
        let effects = launch_agent(&mut core, id, Some(claude_handle()));
        assert!(!effects.iter().any(|e| matches!(e, Effect::Attach { .. })));
        assert!(!core.session(id).unwrap().pending_launch);
        assert_eq!(core.view(), view);
        assert!(core.take_control_outcome("op-1").is_none(), "taken once");
    }

