        );
        seed_run(&mut core, "Dispatch: reviewer@done", RunState::Finalized);
        core.settings.workflows = vec![
            named("Mine"),
            named("Dispatch: reviewer@old"),
            named("Dispatch: reviewer@done"),
            named("Dispatch: reviewer@x"),
        ];
        let effects = control(
