    fn hook(core: &mut AppCore, id: RecordId, kind: EventKind, at: u64) {
        core.dispatch(
            AppAction::Events(vec![SessionEvent {
                record_id: Some(id),
                ..event(kind, at)
            }]),
            Clock::at(at + 1),
        );
    }

    fn stopped() -> EventKind {
        EventKind::Stopped {
            last_message: None,
            pending: None,
        }
    }

    /// A background task's notification or a harness reminder starts a
