            draft.qr = qr_texture(ui.ctx(), &payload).map(|t| (window.code.clone(), t));
        }
        ui.horizontal(|ui| {
            if let Some((_, texture)) = &draft.qr {
                ui.image(egui::load::SizedTexture::from_handle(texture));
