assert!(req.origin_is_own());
assert_eq!(req.cookie.as_deref(), Some("a=1; __Host-sb-x=tok2"));
assert!(read_request(&mut r).unwrap().is_none());
let text = b"GET / HTTP/1.1\r\nHost: h:1\r\nOrigin: https://h:2\r\n\r\n";
let mut r = BufReader::new(&text[..]);
let req = read_request(&mut r).unwrap().unwrap();
assert!(!req.origin_is_own(), "another port is another origin");
let text = b"GET / HTTP/1.1\r\n\r\n";
let mut r = BufReader::new(&text[..]);
let req = read_request(&mut r).unwrap().unwrap();
assert!(!req.origin_is_own(), "no origin is not the page's");
assert_eq!((req.cookie, req.origin, req.host), (None, None, None));

