    let draft = read("draft");
    assert_eq!(draft["body"]["draft"]["text"], "Fix the test. and run");
    assert_eq!(draft["body"]["draft"]["status"], "listening");
    let info = read("info");
    assert_eq!(info["body"]["protocol"], 1);
    assert!(info["body"]["spki_sha256"].is_string());
    let pair = read("pair");
