fn a_tickets_events_are_read_and_a_closable_ticket_is_closed() {
    let mut port = port_dispatching(tickets_status());
    let token = pair(&mut port, "ABCD2345", Scope::Read, "Vision Pro");
    let t = Some(token.as_str());
