    assert!(next > first);
    let (_, last) = get(
        &mut port,
        &format!("/api/v1/sessions/{session}/last-response"),
        Some(&token),
    );
    assert_eq!(
        (
            last["revision"].as_u64().unwrap(),
            last["body"]["n"].as_u64().unwrap()
        ),
        (next, 3)
    );
}

