/// `/ops/{op}` on the port: a creation's status is `done` with its
/// reply, an op never seen is `unknown`; and `/events` without an
/// upgrade is refused by name.
#[test]
fn ops_status_is_read_on_the_port_and_events_needs_an_upgrade() {
    let mut port = port();
